import { $internal } from '../../common';
import { isRelationPair } from '../../relation/utils/is-relation';
import type { Relation } from '../../relation/types';
import type { Trait } from '../../trait/types';
import { isModifier } from '../modifier';
import type { OrModifier, PredicateModifier, QueryHash, QueryParameter } from '../types';

const sortedIDs = new Float64Array(1024); // Use Float64 for larger IDs with relation encoding

const PREDICATE_HASH_OFFSET = 1000000000;

/** Get the unique predicate id for a modifier, if it is a predicate modifier. */
function getPredicateHashId(param: QueryParameter): number | undefined {
    if (!isModifier(param)) return undefined;
    const pred = param as PredicateModifier;
    if (pred.type === 'predicate') return pred.id;
    if (typeof pred.predicateId === 'number') return pred.predicateId;
    return undefined;
}

function encodeModifier(param: QueryParameter, sortedIDs: Float64Array, cursorState: { value: number }) {
    const modifier = param as any;
    const modifierId = modifier.id;
    const traitIds = modifier.traitIds || [];
    const predicateId = getPredicateHashId(param);

    for (let i = 0; i < traitIds.length; i++) {
        const traitId = traitIds[i];
        sortedIDs[cursorState.value++] = modifierId * 100000 + traitId;
    }

    // Include the unique predicate identity so different predicates
    // (or predicate-wrapped modifiers) never share a hash.
    if (predicateId !== undefined) {
        sortedIDs[cursorState.value++] =
            PREDICATE_HASH_OFFSET * 100000 + predicateId + 1;
    }

    // Recurse into Or modifiers so predicate identities are captured.
    if (modifier.type === 'or' && Array.isArray(modifier.modifiers)) {
        for (const nested of (modifier as OrModifier).modifiers) {
            encodeModifier(nested, sortedIDs, cursorState);
        }
    }
}

export const createQueryHash = (parameters: QueryParameter[]): QueryHash => {
    sortedIDs.fill(0);
    const cursor = { value: 0 };

    for (let i = 0; i < parameters.length; i++) {
        const param = parameters[i];

        if (isRelationPair(param)) {
            // Encode relation pair as: (relationTraitId * 1000000) + targetId
            // This ensures unique hashes for different relation/target combinations
            const pairCtx = param[$internal];
            const relation = pairCtx.relation;
            const target = pairCtx.target;

            const relationId = (relation as Relation<Trait>)[$internal].trait.id;
            const targetId = typeof target === 'number' ? target : -1;

            // Combine into a unique hash number
            sortedIDs[cursor.value++] = relationId * 10000000 + targetId + 5000000;
        } else if (isModifier(param)) {
            encodeModifier(param, sortedIDs, cursor);
        } else {
            const traitId = (param as Trait).id;
            sortedIDs[cursor.value++] = traitId;
        }
    }

    // Sort only the portion of the array that has been filled.
    const filledArray = sortedIDs.subarray(0, cursor.value);
    filledArray.sort();

    // Create string key.
    const hash = filledArray.join(',');

    return hash;
};
